let w=window.innerWidth,h=window.innerHeight,scaleDef=3,circleScale=scaleDef,circleGap=10,halftoneColour="#0d0c1d",bgColour="#f8eee6",t=0,offsets=[];function preload(){}function setup(){(canvas=createCanvas(w,h)).style.position="fixed",canvas.style.top="0px",canvas.style.left="0px";for(let e=0;e<w/circleGap+1;e++){offsets[e]=[];for(let c=0;c<h/circleGap+1;c++)offsets[e][c]=random(TWO_PI)}}function draw(){background(bgColour);let e=window.scrollY||document.documentElement.scrollTop,c=document.documentElement.scrollHeight-window.innerHeight,n=1+e/c*10;n=Math.min(n,20/circleScale);for(let l=0;l<w/circleGap+1;l++)for(let o=0;o<h/circleGap+1;o++){let i=l*circleGap,a=o*circleGap;fill(halftoneColour),noStroke();let r=dist(mouseX,mouseY,i,a),s=c/1.5,f=map(Math.min(e,s),0,s,300,25);f=constrain(f,25,300);let d=map(e,0,c,1,.2);d=constrain(d,.1,1);let p=map(e,0,c,1,0);if(p=constrain(p,0,1),r<f){let e=map(r,0,f,0,.8*d);circle(i,a,circleScale*(e=constrain(e,0,.8))*(1+.3*sin(t+offsets[l][o])*p)*n)}else circle(i,a,circleScale*n)}t+=.03}function windowResized(){w=window.innerWidth,h=window.innerHeight,resizeCanvas(w,h)}